{
  "vault": "rsvault-westus",
  "backupPolicy": {
    "name": "NightlyPolicy",
    "policyType": "AzureVirtualMachine",
    "policySubtype": "Enhanced",
    "schedule": { "frequency": "Daily", "startTime": "02:00" },
    "retentionRange": { "daily": 30 },
    "instantRestoreRetentionDays": 7
  },
  "protectedItem": {
    "vmName": "svc-vm-14",
    "osType": "Windows",
    "attachedDataDisks": [
      { "name": "Data disk 1", "lun": 0, "sizeGb": 512, "contents": "Customer and order records" },
      { "name": "Data disk 2", "lun": 1, "sizeGb": 256, "contents": "Read-only reference data, mounted read-only by eight other virtual machines" },
      { "name": "Data disk 3", "lun": 2, "sizeGb": 128, "contents": "Scratch logs regenerated every hour" }
    ]
  },
  "lastJob": { "startedOn": "2026-11-04 02:00", "status": "Failed", "note": "Every job since the shared disk was attached has failed" }
}
